parameters.jsCode:
// Parse the GHL inbound-SMS webhook. Payload shape varies by GHL version, so
// probe the known locations rather than assuming one.
const b = $input.first().json.body || $input.first().json;

const raw = b.phone || b.from || b.contact_phone || b.message?.phone ||
            b.contact?.phone || b.customData?.phone || '';
let d = String(raw).replace(/\D+/g, '');
if (d.length === 11 && d[0] === '1') d = d.slice(1);
const phone = d.length === 10 ? '+1' + d : '';

const text = String(b.message?.body || b.body || b.message || b.sms?.body || '').trim();
const upper = text.toUpperCase();

// READY must be the intent, not merely a substring of some longer sentence.
const isReady = /^\s*READY\b/.test(upper) || upper === 'READY';
const isStop = /^\s*(STOP|STOPALL|UNSUBSCRIBE|CANCEL|END|QUIT)\b/.test(upper);

return [{ json: { phone, text, is_ready: isReady && !isStop, is_stop: isStop } }];

// Round-robin the DEMO POOL. Rotating the from-number spreads outbound volume
// so no single line looks like a dialer.
const POOL = ["+14142508042", "+14143006409", "+14149466486", "+14142061886", "+14142468976"];

const ready = $('Parse Inbound SMS').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.phone === ready.phone);

// Newest matching open intake wins.
const row = rows[0];
if (!row) return [{ json: { found: false, phone: ready.phone } }];

// Rotate on the row id so consecutive demos land on different lines.
const idx = Math.abs(parseInt(row.id, 10) || 0) % POOL.length;

// The script's no-website STAGE_2 variant speaks {{services_typed}} — the
// owner's own words. Rebuild it from what we stored.
const typed = [row.service_1, row.service_2].filter(Boolean).join(' and ');

return [{ json: {
  found: true,
  row_id: row.id,
  from_number: POOL[idx],
  to_number: row.phone,
  first_name: row.first_name || 'there',
  company_name: row.company_name || 'your business',
  // Spoken aloud in STAGE_2 ("I read {{website_url}}"), so hand AVA the bare
  // hostname, never a full https:// URL with a path.
  website_url: (row.website_url || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0] || 'your website',
  city: row.city || 'your area',
  service_1: row.service_1 || 'the work you do',
  service_2: row.service_2 || 'more',
  scraped_fact: row.scraped_fact || 'you list your services right up front',
  services_typed: typed || 'the work you do'
}}];

// Retell post-call webhook -> did a human actually pick up?
const b = $input.first().json.body || $input.first().json;
const call = b.call || b;
const event = b.event || '';

const to = String(call.to_number || '');
const disconnect = String(call.disconnection_reason || '');
const inVoicemail = call.in_voicemail === true || /voicemail/i.test(disconnect);

// Retell fires call_started AND call_ended AND call_analyzed for the SAME call.
// Accepting more than one of them texts the prospect twice (observed in RUN 1.5).
// call_analyzed is the last and richest, so it is the only one we act on; the
// bare-event fallback covers a webhook configured without analysis. A row-level
// 'done' guard downstream is the second line of defence.
const terminal = event === 'call_analyzed' || !event;

const answered = terminal && !inVoicemail &&
                 !/dial_no_answer|dial_busy|dial_failed|no_answer|error/i.test(disconnect);

return [{ json: {
  act: terminal,
  answered,
  to_number: to,
  call_id: call.call_id || '',
  disconnection_reason: disconnect,
  event
}}];

const call = $('Parse Call Result').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const row = rows[0] || null;
// No row at all -> still respond, but never text a stranger.
const alreadyDone = !!(row && row.status === 'done');
// Carry the ROW's identity fields forward: the GHL upsert downstream reads
// $json, and without these it posts an empty body (400 -> no contact id ->
// the post-call SMS 404s with CONVERSATIONS_MSG_CONTACT_ID_NOT_PROVIDED).
return [{ json: Object.assign({}, call, {
  row_id: row ? row.id : null,
  phone: row ? row.phone : (call.to_number || ''),
  first_name: row ? row.first_name : '',
  company_name: row ? row.company_name : '',
  first_send: !!row && !alreadyDone,
  already_done: alreadyDone
})}];

